const ADMIN_HTML = "<!doctype html><html lang=\"ar\" dir=\"rtl\"><head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"robots\" content=\"noindex,nofollow\">\n<title>إدارة مجموعة العلقمي</title><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Zain:wght@300;400;700;800;900&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--navy:#102d56;--blue:#087ed5;--bg:#f3f7fd;--line:#dce6f5;--muted:#6c82a2}*{box-sizing:border-box}body{margin:0;font-family:Zain,Tahoma,sans-serif;color:var(--navy);background:var(--bg);font-size:17px}button,input,select,textarea{font:inherit}button{cursor:pointer}button:disabled{opacity:.5}input,select,textarea{width:100%;padding:11px 12px;border:1px solid #cad8ea;border-radius:12px;background:#fff;color:#173759;outline:0}textarea{min-height:105px;resize:vertical}.btn{border:0;background:var(--blue);color:#fff;padding:10px 17px;border-radius:11px;font-weight:800}.btn.danger{background:#b62d44;color:#fff}.btn.danger:hover{background:#922137}.btn.alt{background:#e6f1ff;color:var(--navy)}.login{max-width:440px;margin:10vh auto;background:#fff;padding:32px;border-radius:24px;box-shadow:0 15px 60px #143d6420;text-align:center}.login h1{font-size:31px;margin:10px 0}.login label{display:block;text-align:right;margin:15px 0 5px}.app{display:none;min-height:100vh}.side{width:240px;background:linear-gradient(170deg,#0a2b4c,#0f477a);color:#fff;padding:24px 16px;position:sticky;top:0;height:100vh}.side h2{font-size:27px;margin:0 8px 4px}.side small{display:block;color:#b9d7ef;margin:0 8px 22px}.side button{display:block;width:100%;border:0;border-radius:12px;background:transparent;color:#d4e7ff;text-align:right;padding:12px;margin:5px 0;font-weight:700}.side button.selected,.side button:hover{background:#ffffff22;color:#fff}.content{flex:1;padding:25px;max-width:calc(100% - 240px)}.top{display:flex;align-items:center;justify-content:space-between;gap:15px}.pill{display:inline-block;background:#e1efff;color:#175899;font-weight:800;padding:4px 11px;border-radius:20px}.card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:20px;margin-top:20px;box-shadow:0 10px 25px #0b457007}.flex{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.between{justify-content:space-between}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.grid .card{margin-top:0}.muted{color:var(--muted)}.table-scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;min-width:820px}td,th{padding:12px;border-bottom:1px solid var(--line);text-align:right}th{color:#6584a8;font-weight:700}tr:last-child td{border:0}.price-old{text-decoration:line-through;text-decoration-color:#db3046;text-decoration-thickness:2px;color:#9b6b75}.sale{font-weight:900;color:#1172c2}.editgrid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}.editgrid label{font-weight:700}.editgrid label input,.editgrid label select,.editgrid label textarea{margin-top:6px}.full{grid-column:1/-1}.note{background:#eff8ff;border-right:3px solid #139ee1;padding:11px;border-radius:8px;margin:15px 0}.note.good{background:#eefaf6;border-color:#12a17f}.help{font-size:13px;color:#7188a1}.search{max-width:360px}.site-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.site-grid .full{grid-column:1/-1}.image-list{display:flex;gap:9px;flex-wrap:wrap;margin:10px 0}.image-item{width:100px;height:100px;border:1px solid var(--line);border-radius:13px;background:#f6faff;position:relative;overflow:hidden}.image-item img{width:100%;height:100%;object-fit:contain}.image-item button{position:absolute;left:4px;top:4px;width:26px;height:26px;border:0;border-radius:50%;background:#b82f43;color:#fff;font-weight:900}.upload-box{border:2px dashed #bad7eb;background:#f7fbff;border-radius:14px;padding:14px;text-align:center}.upload-box input{border:0;background:transparent}.preview{width:100%;height:190px;object-fit:contain;background:#edf6ff;border:1px solid #d8e8f5;border-radius:15px;margin-top:8px}.multi{min-height:140px}.scopebox{grid-column:1/-1;background:#f7fbff;border:1px solid #dce8f3;border-radius:12px;padding:12px}.coupon-code{font-family:monospace;direction:ltr;unicode-bidi:embed;font-weight:900}#msg{position:fixed;bottom:15px;left:15px;background:#163d65;color:white;padding:12px 20px;border-radius:12px;display:none;z-index:90}dialog{border:0;border-radius:18px;max-width:780px;width:calc(100% - 25px);max-height:92vh;overflow:auto;padding:23px;box-shadow:0 20px 90px #13294455}dialog::backdrop{background:#122b4499}.actions{display:flex;justify-content:flex-end;gap:9px;margin-top:20px}h1{font-size:32px}h3{font-size:23px;margin:0 0 9px}\n@media(max-width:950px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:730px){.app[style*=\"flex\"]{display:block!important}.side{position:static;width:auto;height:auto;padding:12px}.side h2{font-size:22px}.side small{display:none}.side button{display:inline-block;width:auto;padding:8px 11px}.content{max-width:none;padding:15px}.grid,.site-grid,.editgrid{grid-template-columns:1fr}.full,.site-grid .full{grid-column:auto}}\n.discount-editor{border:1px solid #cfe2f1;border-radius:14px;background:#f7fbff;padding:15px}.discount-switch{display:flex;align-items:center;gap:10px;font-weight:800;cursor:pointer}.discount-switch input{width:22px;height:22px;accent-color:#087ed5;flex-shrink:0}.discount-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.discount-preview{margin-top:12px;padding:12px 14px;border-radius:12px;background:#eaf7f2;color:#145747;line-height:1.9}.discount-preview.invalid{background:#fff0f2;color:#a52b40}.discount-final{border-top:1px solid #cfe7df;margin-top:6px;padding-top:6px;font-size:19px}#discountFields[hidden]{display:none!important}@media(max-width:730px){.discount-grid{grid-template-columns:1fr}}\n.status-badge{display:inline-flex;align-items:center;gap:6px;padding:5px 11px;border-radius:20px;font-size:15px;font-weight:800;background:#edf3fb;color:#315579;white-space:nowrap}.status-badge.fulfilled{background:#e1f5e9;color:#116b3e;border:1px solid #addfc0}.status-badge.cancelled{background:#fde9ed;color:#a62e44}.order-actions{display:flex;gap:8px;flex-wrap:wrap;min-width:190px}.report-filters{display:grid;grid-template-columns:repeat(4,minmax(130px,1fr)) auto;gap:12px;align-items:end;margin-top:15px}.report-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:20px 0}.metric{margin:0!important}.metric strong{display:block;font-size:27px;margin-top:9px}.metric.positive strong{color:#14754d}.invoice-date-row td{background:#eaf3ff;font-weight:800;color:#175899}.status-badge.rejected{background:#fde9ed;color:#a62e44}tfoot th{background:#f0f5fd}@media(max-width:1000px){.report-filters{grid-template-columns:repeat(2,minmax(0,1fr))}.report-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:520px){.report-metrics{grid-template-columns:1fr}.report-filters{grid-template-columns:1fr}.metric strong{font-size:25px}}</style><script defer src=\"/admin-assets/invoice.js\"></script></head><body>\n<div id=\"login\" class=\"login\"><div style=\"font-size:44px\">💧</div><h1>إدارة مجموعة العلقمي</h1><p class=\"muted\">المنتجات • الخصومات • الكوبونات • واجهة الموقع</p><form id=\"loginForm\"><label>كلمة مرور الإدارة</label><input id=\"password\" type=\"password\" autocomplete=\"current-password\" required minlength=\"12\"><button class=\"btn\" style=\"width:100%;margin-top:15px\">تسجيل الدخول</button></form><p class=\"muted\">البيانات محفوظة في Cloudflare D1.</p></div>\n<div id=\"app\" class=\"app\"><aside class=\"side\"><h2>💧 العلقمي</h2><small>لوحة إدارة المتجر</small><button data-tab=\"home\" class=\"selected\">نظرة عامة</button><button data-tab=\"products\">المنتجات والتخفيضات</button><button data-tab=\"coupons\">الكوبونات</button><button data-tab=\"site\">واجهة الموقع</button><button data-tab=\"orders\">الطلبات</button><button data-tab=\"reports\">التقارير والفواتير</button><button id=\"logout\">تسجيل خروج</button></aside>\n<main class=\"content\"><div class=\"top\"><div><span class=\"pill\">Cloudflare D1</span><h1 id=\"heading\">لوحة الإدارة</h1></div><a href=\"https://alalqami.pages.dev/\" target=\"_blank\" rel=\"noopener\">فتح المتجر ↗</a></div><div id=\"pane\"></div></main></div>\n<dialog id=\"dialog\"><h3 id=\"dialogTitle\">تعديل</h3><form id=\"editForm\"><div id=\"editFields\" class=\"editgrid\"></div><div class=\"actions\"><button type=\"button\" class=\"btn alt\" id=\"closeDialog\">إلغاء</button><button class=\"btn\" id=\"saveDialog\">حفظ التغييرات</button></div></form></dialog><div id=\"msg\"></div>\n<script>\nconst $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));\nconst e=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst money=n=>Number(n||0).toLocaleString('en-US')+' د.ع';\nconst orderStatuses={new:'بانتظار تأكيد التاجر',confirmed:'مؤكد من التاجر',fulfilled:'مكتمل',cancelled:'ملغي',rejected:'مرفوض'};\nconst cats={systems:'أجهزة التحلية',filters:'الشمعات والفلاتر',spares:'قطع الغيار',other:'أخرى'};\nlet state={products:[],coupons:[],orders:[],site:{},tab:'home',edit:null,editImages:[]};\nfunction toast(s){const x=$('#msg');x.textContent=s;x.style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>x.style.display='none',4200)}\nasync function api(path,opt={}){const r=await fetch(path,{credentials:'same-origin',...opt,headers:{'Content-Type':'application/json',...(opt.headers||{})}});let j={};try{j=await r.json()}catch{}if(!r.ok)throw Error(j.error||'حدث خطأ');return j}\nfunction show(ok){$('#login').style.display=ok?'none':'block';$('#app').style.display=ok?'flex':'none'}\nfunction parseImages(p){try{return (Array.isArray(p.images)?p.images:JSON.parse(p.images_json||'[]')).filter(Boolean)}catch{return p.image?[p.image]:[]}}\nasync function load(){try{const j=await api('/api/admin/state');state.products=j.products||[];state.coupons=j.coupons||[];state.orders=j.orders||[];state.site=j.site||{};state.products.forEach(p=>p.images=parseImages(p));show(true);render()}catch{show(false)}}\nfunction field(n,label,val,type='text',more=''){return '<label>'+label+'<input name=\"'+n+'\" type=\"'+type+'\" '+more+' value=\"'+e(val??'')+'\"></label>'}\nfunction area(n,label,val){return '<label class=\"full\">'+label+'<textarea name=\"'+n+'\">'+e(val??'')+'</textarea></label>'}\nfunction select(n,label,val,options,more=''){return '<label>'+label+'<select name=\"'+n+'\" '+more+'>'+options.map(x=>'<option value=\"'+e(x[0])+'\" '+(String(val)===String(x[0])?'selected':'')+'>'+e(x[1])+'</option>').join('')+'</select></label>'}\nfunction render(){$$('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab===state.tab));const p=$('#pane');$('#heading').textContent={home:'نظرة عامة',products:'إدارة المنتجات والتخفيضات',coupons:'كوبونات الخصم',site:'واجهة الموقع',orders:'الطلبات',reports:'التقارير والفواتير'}[state.tab];\nif(state.tab==='home'){p.innerHTML='<div class=\"note good\">النظام مربوط فعلياً على Cloudflare. المنتج المخفي لا يظهر للزبون.</div><div class=\"grid\"><div class=\"card\"><h3>'+state.products.length+'</h3>منتج</div><div class=\"card\"><h3>'+state.products.filter(x=>x.active).length+'</h3>منشور</div><div class=\"card\"><h3>'+state.products.filter(x=>x.sale_price!==null).length+'</h3>عليه تخفيض</div><div class=\"card\"><h3>'+state.coupons.length+'</h3>كوبون</div></div><div class=\"card\"><h3>تعديل واجهة الموقع</h3><p>غيّر العنوان والصورة وبطاقات العروض من نفس اللوحة.</p><button class=\"btn\" id=\"goSite\">تعديل الواجهة</button></div>';$('#goSite').onclick=()=>{state.tab='site';render()};return}\nif(state.tab==='reports'){reportsPane(p);return}if(state.tab==='products'){productsPane(p);return}if(state.tab==='coupons'){couponsPane(p);return}if(state.tab==='site'){sitePane(p);return}ordersPane(p)}\nfunction productsPane(p){p.innerHTML='<div class=\"card\"><div class=\"flex between\"><div><h3>المنتجات</h3><span class=\"muted\">'+state.products.length+' منتج</span></div><button class=\"btn\" id=\"newProduct\">+ إضافة منتج</button></div><div class=\"flex\" style=\"margin-top:14px\"><input id=\"search\" class=\"search\" placeholder=\"ابحث باسم المنتج أو النوع أو الماركة\"></div><div id=\"ptable\" class=\"table-scroll\"></div></div>';$('#newProduct').onclick=()=>editProduct(null);$('#search').oninput=drawProducts;drawProducts()}\nfunction drawProducts(){const box=$('#ptable');if(!box)return;const q=($('#search')?.value||'').toLowerCase();const xs=state.products.filter(x=>(x.name+' '+(x.product_type||'')+' '+x.brand+' '+x.category).toLowerCase().includes(q));box.innerHTML='<table><thead><tr><th>المنتج</th><th>النوع / المجموعة</th><th>السعر</th><th>الصور</th><th>النشر</th><th></th></tr></thead><tbody>'+xs.map(x=>'<tr><td><b>'+e(x.name)+'</b><br><small>'+e(x.brand||'')+'</small></td><td>'+e(x.product_type||'—')+'<br><small>'+e(cats[x.category]||x.category)+'</small></td><td>'+(x.sale_price!==null?'<span class=\"price-old\">'+money(x.price)+'</span><br><span class=\"sale\">'+money(x.sale_price)+'</span>':money(x.price))+'</td><td>'+parseImages(x).length+'</td><td>'+(x.active?'منشور':'مخفي')+'</td><td><div class=\"flex\"><button class=\"btn alt\" data-product=\"'+e(x.id)+'\">تعديل</button><button class=\"btn danger\" data-delete-product=\"'+e(x.id)+'\" aria-label=\"حذف المنتج '+e(x.name)+' نهائياً\">حذف</button></div></td></tr>').join('')+'</tbody></table>';$$('[data-product]').forEach(b=>b.onclick=()=>editProduct(state.products.find(x=>x.id===b.dataset.product)));$$('[data-delete-product]').forEach(b=>b.onclick=()=>deleteProduct(b.dataset.deleteProduct,b))}\nasync function deleteProduct(id,button){\n const product=state.products.find(x=>x.id===id);\n if(!product||!confirm('حذف المنتج «'+product.name+'» نهائياً من المتجر؟ لا يمكن التراجع عن الحذف، وتبقى بيانات الطلبات والفواتير السابقة محفوظة.'))return;\n button.disabled=true;\n try{await api('/api/admin/products/'+encodeURIComponent(id),{method:'DELETE',body:JSON.stringify({confirm_id:id})});toast('تم حذف المنتج نهائياً');await load()}\n catch(err){toast(err.message);button.disabled=false}\n}\nasync function downloadInvoice(id,button){\n button.disabled=true;const label=button.textContent;button.textContent='جاري تجهيز الفاتورة...';\n try{if(!window.AlqamiInvoice)throw Error('جاري تحميل أداة الفواتير؛ حاول بعد لحظات.');const result=await api('/api/admin/orders/'+encodeURIComponent(id)+'/invoice');window.AlqamiInvoice.download(result.order)}\n catch(err){toast(err.message)}finally{button.disabled=false;button.textContent=label}\n}\n\nfunction dialog(kind,id,title,html){state.edit={kind,id};$('#dialogTitle').textContent=title;$('#editFields').innerHTML=html;$('#dialog').showModal()}\nfunction imageList(){return '<div class=\"full\"><b>صور المنتج</b><div class=\"image-list\" id=\"imageList\">'+state.editImages.map((u,i)=>'<div class=\"image-item\"><img src=\"'+e(u)+'\"><button type=\"button\" data-remove-img=\"'+i+'\">×</button></div>').join('')+'</div><div class=\"upload-box\"><b>إضافة صور من الجهاز</b><p class=\"help\">حتى 8 صور بالمجموع. تُضغط الصور تلقائياً قبل الرفع.</p><input id=\"productFiles\" type=\"file\" accept=\"image/jpeg,image/png,image/webp\" multiple></div></div>'}\nfunction editProduct(p){p=p||{id:'',name:'',product_type:'',category:'systems',brand:'',description:'',price:0,sale_price:null,active:1,images:[]};state.editImages=parseImages(p);dialog('product',p.id||'','إضافة أو تعديل منتج',field('name','اسم المنتج',p.name,'text','required maxlength=\"180\"')+field('product_type','نوع المنتج',p.product_type||'','text','placeholder=\"مثلاً: RO سبع مراحل\" maxlength=\"100\"')+select('category','المجموعة',p.category,Object.entries(cats))+field('brand','الماركة',p.brand||'','text','maxlength=\"70\"')+field('price','السعر الأصلي بالدينار',p.price,'number','required min=\"0\"')+productDiscountEditor(p)+select('active','الحالة',String(p.active),[['1','منشور في المتجر'],['0','مخفي / مسودة']])+area('description','معلومات ووصف المنتج',p.description||'')+imageList());initProductDiscountEditor(p);$('#editFields').onclick=ev=>{const b=ev.target.closest('[data-remove-img]');if(!b)return;state.editImages.splice(Number(b.dataset.removeImg),1);drawEditImages()}}\nfunction calculateProductDiscount(priceInput, enabled, kind, valueInput) {\n  const price = Number(priceInput);\n  if (String(priceInput).trim() === '' || !Number.isSafeInteger(price) || price < 0 || price > 1000000000) {\n    return { error: 'اكتب سعر أصلي صحيح بالدينار.' };\n  }\n  if (!enabled) return { price, amount: 0, percent: 0, salePrice: null };\n  if (price === 0) return { error: 'السعر الأصلي لازم يكون أكبر من صفر حتى تفعّل الخصم.' };\n  const text = String(valueInput).trim();\n  const value = Number(text);\n  if (!text || !Number.isFinite(value) || value <= 0) return { error: 'اكتب قيمة خصم أكبر من صفر.' };\n  let amount;\n  if (kind === 'fixed') {\n    if (!Number.isSafeInteger(value) || value > price) return { error: 'مبلغ الخصم لازم يكون دينار صحيح وما يتجاوز السعر الأصلي.' };\n    amount = value;\n  } else if (kind === 'percent') {\n    if (!/^\\d+(?:\\.\\d{1,8})?$/.test(text) || value > 100) return { error: 'اكتب نسبة صحيحة أكبر من صفر ولحد 100%.' };\n    const decimals = text.split('.')[1]?.length || 0;\n    amount = Number(BigInt(price) * BigInt(text.replace('.', '')) / (100n * 10n ** BigInt(decimals)));\n    if (amount < 1) return { error: 'الخصم المحسوب أقل من دينار؛ زيد النسبة أو اختار مبلغ بالدينار.' };\n  } else return { error: 'اختار نوع الخصم.' };\n  return { price, amount, percent: amount * 100 / price, salePrice: price - amount };\n}\n\nfunction productDiscountEditor(product) {\n  const enabled = product.sale_price !== null && product.sale_price !== undefined && product.sale_price !== '';\n  const amount = enabled ? Number(product.price) - Number(product.sale_price) : '';\n  return '<div class=\"full discount-editor\"><label class=\"discount-switch\"><input id=\"discountEnabled\" type=\"checkbox\" ' + (enabled ? 'checked' : '') + '><span>تفعيل خصم على المنتج</span></label><p class=\"help\">فعّل المربع حتى تختار خصم بمبلغ أو نسبة. عند الإيقاف يرجع السعر الأصلي بدون شطب.</p><div id=\"discountFields\"' + (enabled ? '' : ' hidden') + '><div class=\"discount-grid\">' + select('discount_kind', 'نوع الخصم', 'fixed', [['fixed', 'مبلغ بالدينار'], ['percent', 'نسبة مئوية %']], 'id=\"discountKind\"') + field('discount_value', 'قيمة الخصم', amount, 'number', 'id=\"discountValue\" min=\"1\" step=\"1\" inputmode=\"decimal\"') + '</div><div id=\"discountPreview\" class=\"discount-preview\" aria-live=\"polite\"></div></div></div>';\n}\n\nlet productDiscountDraft = null;\n\nfunction initProductDiscountEditor(product) {\n  productDiscountDraft = null;\n  const price = $('#editFields [name=price]');\n  const kind = $('#discountKind');\n  const value = $('#discountValue');\n  const enabled = $('#discountEnabled');\n  const update = () => {\n    productDiscountDraft = calculateProductDiscount(price.value, enabled.checked, kind.value, value.value);\n    drawProductDiscountPreview();\n  };\n  enabled.onchange = update;\n  value.oninput = update;\n  price.oninput = update;\n  kind.onchange = () => {\n    // A display-mode switch must never change an existing discount via a rounded percentage.\n    const previous = productDiscountDraft;\n    if (previous && !previous.error && previous.salePrice !== null) {\n      const percentage = previous.amount * 100 / previous.price;\n      value.value = kind.value === 'fixed' ? String(previous.amount) : (Number(percentage.toFixed(2)) > 0 ? percentage.toFixed(2) : percentage.toFixed(8));\n      productDiscountDraft = previous;\n      drawProductDiscountPreview();\n    } else update();\n  };\n  update();\n}\n\nfunction drawProductDiscountPreview() {\n  const enabled = $('#discountEnabled').checked;\n  const kind = $('#discountKind');\n  const value = $('#discountValue');\n  $('#discountFields').hidden = !enabled;\n  kind.disabled = value.disabled = !enabled;\n  value.required = enabled;\n  const label = value.closest('label');\n  label.firstChild.textContent = kind.value === 'percent' ? 'نسبة الخصم %' : 'مبلغ الخصم بالدينار';\n  value.min = kind.value === 'percent' ? '0.00000001' : '1';\n  value.step = kind.value === 'percent' ? 'any' : '1';\n  const price = Number($('#editFields [name=price]').value);\n  value.max = kind.value === 'percent' ? '100' : String(Math.max(0, price));\n  const preview = $('#discountPreview');\n  const result = productDiscountDraft;\n  value.setCustomValidity(enabled && result?.error ? result.error : '');\n  if (!enabled) { preview.textContent = ''; return; }\n  if (result?.error) {\n    preview.className = 'discount-preview invalid';\n    preview.textContent = result.error;\n    return;\n  }\n  const percentage = result.percent.toLocaleString('en-US', { maximumFractionDigits: 2 });\n  preview.className = 'discount-preview';\n  preview.innerHTML = '<div>مبلغ الخصم: <b>' + money(result.amount) + '</b></div><div>نسبة الخصم من السعر الأصلي: <b dir=\"ltr\">' + percentage + '%</b></div><div class=\"discount-final\">السعر بعد الخصم: <b>' + money(result.salePrice) + '</b></div>' + (result.salePrice === 0 ? '<p class=\"help\">تنبيه: هذا الخصم يجعل السعر النهائي صفر دينار.</p>' : '');\n}\n\nfunction readProductDiscount() {\n  if (!$('#discountEnabled').checked) return { salePrice: null };\n  if (!productDiscountDraft || productDiscountDraft.error) throw Error(productDiscountDraft?.error || 'راجع قيمة الخصم.');\n  return productDiscountDraft;\n}\n\nfunction drawEditImages(){const x=$('#imageList');if(x)x.innerHTML=state.editImages.map((u,i)=>'<div class=\"image-item\"><img src=\"'+e(u)+'\"><button type=\"button\" data-remove-img=\"'+i+'\">×</button></div>').join('')}\nfunction compressImage(file){if(!/^image\\/(jpeg|png|webp)$/.test(file.type))return Promise.reject(Error('صيغة الصورة غير مدعومة'));return new Promise((resolve,reject)=>{const fr=new FileReader();fr.onerror=()=>reject(Error('تعذر قراءة الصورة'));fr.onload=()=>{const img=new Image();img.onerror=()=>reject(Error('تعذر معالجة الصورة'));img.onload=()=>{let w=img.width,h=img.height,max=1200;if(w>max||h>max){const r=Math.min(max/w,max/h);w=Math.round(w*r);h=Math.round(h*r)}const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);c.toBlob(blob=>{if(!blob)return reject(Error('تعذر ضغط الصورة'));const rr=new FileReader();rr.onload=()=>resolve(rr.result);rr.onerror=()=>reject(Error('تعذر تجهيز الصورة'));rr.readAsDataURL(blob)},'image/webp',.76)};img.src=fr.result};fr.readAsDataURL(file)})}\nasync function uploadFiles(files){const urls=[];for(const f of files){const data=await compressImage(f);const r=await api('/api/admin/media',{method:'POST',body:JSON.stringify({data})});urls.push(r.url)}return urls}\nfunction couponsPane(p){p.innerHTML='<div class=\"card\"><div class=\"flex between\"><h3>الكوبونات</h3><button class=\"btn\" id=\"newCoupon\">+ كوبون جديد</button></div><div class=\"table-scroll\"><table><thead><tr><th>الكود</th><th>الخصم</th><th>يشمل</th><th>البداية · بغداد</th><th>النهاية · بغداد</th><th>الاستخدام</th><th>الحالة</th><th></th></tr></thead><tbody>'+state.coupons.map(c=>'<tr><td><span class=\"coupon-code\">'+e(c.code)+'</span></td><td>'+(c.kind==='percent'?e(c.value)+'%':money(c.value))+'</td><td>'+e(c.scope)+'</td><td>'+e(couponDateLabel(c.starts_at))+'</td><td>'+e(couponDateLabel(c.ends_at))+'</td><td>'+c.uses+' / '+c.max_uses+'</td><td>'+(c.enabled?'فعال':'متوقف')+'</td><td><div class=\"flex\"><button class=\"btn alt\" data-coupon=\"'+e(c.code)+'\">تعديل</button><button class=\"btn danger\" data-delete-coupon=\"'+e(c.code)+'\" aria-label=\"حذف الكوبون '+e(c.code)+' نهائياً\">حذف</button></div></td></tr>').join('')+'</tbody></table></div></div>';$('#newCoupon').onclick=()=>editCoupon(null);$$('[data-coupon]').forEach(b=>b.onclick=()=>editCoupon(state.coupons.find(x=>x.code===b.dataset.coupon)));$$('[data-delete-coupon]').forEach(b=>b.onclick=()=>deleteCoupon(b.dataset.deleteCoupon,b))}\nasync function deleteCoupon(code,button){\n  if(!confirm('حذف الكوبون «'+code+'» نهائياً؟ لن يعمل بعدها، ولا يمكن التراجع عن الحذف. تبقى تفاصيل الطلبات السابقة محفوظة.'))return;\n  button.disabled=true;\n  try{await api('/api/admin/coupons/'+encodeURIComponent(code),{method:'DELETE',body:JSON.stringify({confirm_code:code})});toast('تم حذف الكوبون نهائياً');await load()}\n  catch(err){toast(err.message);button.disabled=false}\n}\n// Stored coupon dates are UTC; every admin date control uses Baghdad time.\nfunction dt(v){if(!v)return '';const date=new Date(String(v).replace(' ','T')+'Z');return Number.isNaN(date.getTime())?'':new Date(date.getTime()+3*60*60*1000).toISOString().slice(0,16)}\nfunction utcCouponDate(v){return v?new Date(v+':00+03:00').toISOString():null}\nfunction couponDateLabel(v){return dt(v).replace('T',' ')||'—'}\nfunction scopeUI(c){let ids=[];try{ids=Array.isArray(c.scope_ids)?c.scope_ids:JSON.parse(c.scope_ids||'[]')}catch{}const box=$('#scopeBox'),scope=$('[name=scope]').value;if(scope==='all'){box.innerHTML='<span class=\"muted\">الكوبون يشمل كل المتجر.</span>';return}if(scope==='category'){box.innerHTML='<label>المجموعة<select id=\"scopeCategory\">'+Object.entries(cats).map(x=>'<option value=\"'+x[0]+'\" '+(ids.includes(x[0])?'selected':'')+'>'+x[1]+'</option>').join('')+'</select></label>';return}box.innerHTML='<label>المنتجات<select id=\"scopeProducts\" class=\"multi\" multiple>'+state.products.map(x=>'<option value=\"'+e(x.id)+'\" '+(ids.includes(x.id)?'selected':'')+'>'+e(x.name)+'</option>').join('')+'</select></label><p class=\"help\">اختار أكثر من منتج باستخدام Ctrl أو Command.</p>'}\nfunction editCoupon(c){c=c||{code:'',kind:'percent',value:10,scope:'all',scope_ids:'[]',min_total:0,max_uses:1,starts_at:'',ends_at:'',allow_stacking:0,enabled:1};dialog('coupon',c.code||'','إنشاء أو تعديل كوبون',field('code','رمز الكوبون',c.code,'text',c.code?'readonly':'required maxlength=\"32\"')+select('kind','نوع الخصم',c.kind,[['percent','نسبة مئوية %'],['fixed','مبلغ ثابت بالدينار']])+field('value','قيمة الخصم',c.value,'number','required min=\"1\"')+select('scope','يشمل',c.scope,[['all','المتجر كله'],['category','مجموعة محددة'],['products','منتجات محددة']],'id=\"scopeSelect\"')+'<div class=\"scopebox\" id=\"scopeBox\"></div>'+field('min_total','الحد الأدنى للطلب',c.min_total,'number','min=\"0\"')+field('max_uses','عدد الاستخدامات',c.max_uses,'number','required min=\"1\"')+field('starts_at','تاريخ ووقت البداية — بغداد',dt(c.starts_at),'datetime-local')+field('ends_at','تاريخ ووقت الانتهاء — بغداد',dt(c.ends_at),'datetime-local')+select('allow_stacking','دمج مع تخفيض المنتج',String(c.allow_stacking),[['0','ممنوع'],['1','مسموح']])+select('enabled','الحالة',String(c.enabled),[['1','فعّال'],['0','موقوف']])+'<p class=\"note full\">كل الأوقات بتوقيت بغداد. اترك البداية فارغة ليعمل الكوبون فوراً، واترك النهاية فارغة إذا لا تريد تاريخ انتهاء.</p>');scopeUI(c);$('#scopeSelect').onchange=()=>scopeUI({scope_ids:'[]'})}\nfunction sitePane(p){const s=state.site||{};p.innerHTML='<form id=\"siteForm\"><div class=\"card\"><div class=\"flex between\"><div><h3>الشاشة الرئيسية</h3><span class=\"muted\">غيّر النص والصورة بأي وقت.</span></div><button class=\"btn\">حفظ واجهة الموقع</button></div><div class=\"site-grid\" style=\"margin-top:15px\">'+field('hero_eyebrow','النص الصغير فوق العنوان',s.hero_eyebrow||'عالم المياه النقية، أقرب لبيتك')+field('hero_title1','العنوان - السطر الأول',s.hero_title1||'اختيارك للنقاء.')+field('hero_title2','العنوان - السطر الثاني',s.hero_title2||'بداية راحة بيتك.')+area('hero_description','وصف الشاشة الرئيسية',s.hero_description||'أجهزة تحلية المياه وملحقاتها من مجموعة العلقمي.')+field('hero_primary','نص الزر الرئيسي',s.hero_primary||'اكتشف الأجهزة')+field('hero_secondary','نص الزر الثاني',s.hero_secondary||'خدمات التركيب والصيانة')+'<label class=\"full\">صورة الشاشة الرئيسية<input id=\"heroFile\" type=\"file\" accept=\"image/jpeg,image/png,image/webp\">'+(s.hero_image?'<img class=\"preview\" src=\"'+e(s.hero_image)+'\">':'<span class=\"help\">إذا ما رفعت صورة يبقى الجهاز الحالي.</span>')+'</label></div></div>'+promoCard(1,s)+promoCard(2,s)+'</form>';$('#siteForm').onsubmit=saveSite}\nfunction promoCard(n,s){return '<div class=\"card\"><h3>بطاقة '+n+' — عرض / محتوى</h3><div class=\"site-grid\">'+field('promo'+n+'_kicker','التصنيف الصغير',s['promo'+n+'_kicker']||(n===1?'أجهزة تنقية المياه':'خدمة ما بعد الشراء'))+area('promo'+n+'_title','العنوان',s['promo'+n+'_title']||(n===1?'اختيارك الأفضل\\nيبدأ من التفاصيل.':'نساعدك\\nتبقي جهازك بأفضل أداء.'))+area('promo'+n+'_description','الوصف',s['promo'+n+'_description']||(n===1?'تصفّح الأجهزة حسب الماركة والسعر، وخلي القرار أوضح.':'طلبات الصيانة والتركيب داخل كربلاء، بخطوات مريحة.'))+field('promo'+n+'_button','نص الزر',s['promo'+n+'_button']||(n===1?'اكتشف الأجهزة':'طلب خدمة'))+field('promo'+n+'_href','الرابط',s['promo'+n+'_href']||(n===1?'#/shop':'#/services'))+'<label class=\"full\">صورة البطاقة<input id=\"promo'+n+'File\" type=\"file\" accept=\"image/jpeg,image/png,image/webp\">'+(s['promo'+n+'_image']?'<img class=\"preview\" src=\"'+e(s['promo'+n+'_image'])+'\">':'<span class=\"help\">اختياري</span>')+'</label></div></div>'}\nasync function saveSite(ev){ev.preventDefault();const btn=ev.submitter||$('#siteForm button');btn.disabled=true;try{const d=Object.fromEntries(new FormData(ev.target));for(const n of ['hero','promo1','promo2']){const f=$('#'+n+'File')?.files?.[0];if(f){const u=await uploadFiles([f]);d[n+'_image']=u[0]}else d[n+'_image']=state.site[n+'_image']||''}await api('/api/admin/site',{method:'PUT',body:JSON.stringify(d)});toast('تم حفظ واجهة الموقع');await load();state.tab='site';render()}catch(err){toast(err.message)}finally{btn.disabled=false}}\nfunction ordersPane(p){p.innerHTML='<div class=\"card\"><h3>الطلبات</h3><p class=\"note\">فتح واتساب لا يثبت إرسال الرسالة. الطلب الجديد يبقى بانتظار تأكيد التاجر؛ أكده فقط بعد وصول رسالة الزبون. الطلبات المسجلة قبل الإصلاح تحتاج مراجعة أيضاً.</p><div class=\"table-scroll\"><table><thead><tr><th>التاريخ</th><th>الطلب</th><th>الزبون</th><th>المبلغ</th><th>الكوبون</th><th>الحالة</th><th></th></tr></thead><tbody>'+state.orders.map(o=>'<tr><td>'+e(o.created_at)+'</td><td>'+e(o.id.slice(0,8))+'</td><td>'+e(o.customer_name)+'<br>'+e(o.phone)+'</td><td>'+money(o.total)+'</td><td>'+e(o.coupon_code_snapshot||o.coupon_code||'—')+'</td><td><span class=\"status-badge '+e(o.status)+'\">'+(o.status==='fulfilled'?'✓ ':'')+e(orderStatuses[o.status]||o.status)+'</span></td><td><div class=\"order-actions\"><button class=\"btn alt\" data-order=\"'+e(o.id)+'\">تعديل</button>'+(o.invoice_archived?'<span class=\"muted\">الفاتورة مؤرشفة</span>':'<button class=\"btn alt\" data-invoice=\"'+e(o.id)+'\">تحميل فاتورة PDF</button>')+'<button class=\"btn alt\" data-archive-invoice=\"'+e(o.id)+'\" data-archived=\"'+(o.invoice_archived?1:0)+'\">'+(o.invoice_archived?'استعادة الفاتورة':'أرشفة الفاتورة')+'</button></div></td></tr>').join('')+'</tbody></table></div></div>';$$('[data-order]').forEach(b=>b.onclick=()=>editOrder(state.orders.find(x=>x.id===b.dataset.order)));$$('[data-invoice]').forEach(b=>b.onclick=()=>downloadInvoice(b.dataset.invoice,b));$$('[data-archive-invoice]').forEach(b=>b.onclick=()=>archiveInvoice(b.dataset.archiveInvoice,Number(b.dataset.archived)===0,b))}\nfunction editOrder(o){dialog('order',o.id,'تغيير حالة الطلب',select('status','حالة الطلب',o.status,Object.entries(orderStatuses)))}\n/* ALQAMI_REPORTS_START */\nconst reportGroupLabels={day:'يومي',week:'أسبوعي - يبدأ السبت',month:'شهري',year:'سنوي'};\nlet reportRun=0;\nfunction baghdadToday(){return new Date(Date.now()+3*3600000).toISOString().slice(0,10)}\nfunction reportPreset(kind){\n const today=baghdadToday(),date=new Date(today+'T00:00:00Z'),year=date.getUTCFullYear(),month=date.getUTCMonth();\n const iso=d=>d.toISOString().slice(0,10);\n if(kind==='day')return {from:today,to:today,group:'day'};\n if(kind==='week'){const first=new Date(date);first.setUTCDate(first.getUTCDate()-(first.getUTCDay()+1)%7);const last=new Date(first);last.setUTCDate(last.getUTCDate()+6);return {from:iso(first),to:iso(last),group:'day'}}\n if(kind==='year')return {from:year+'-01-01',to:year+'-12-31',group:'month'};\n return {from:iso(new Date(Date.UTC(year,month,1))),to:iso(new Date(Date.UTC(year,month+1,0))),group:'day'};\n}\nfunction reportQuery(filters){return new URLSearchParams({from:filters.from,to:filters.to,group:filters.group}).toString()}\nfunction reportsPane(p){\n if(!state.reportFilters)state.reportFilters={...reportPreset('month'),preset:'month',archive:'active'};\n const f=state.reportFilters;\n p.innerHTML='<form id=\"reportForm\" class=\"card\"><div class=\"flex between\"><div><h3>تقارير المبيعات والفواتير</h3><p class=\"muted\">اختر الفترة، راجع العدادات، وحمّل تقرير PDF.</p></div><button type=\"button\" class=\"btn alt\" id=\"exportReport\" disabled>تحميل التقرير PDF</button></div><div class=\"report-filters\">'+select('preset','الفترة',f.preset,[['day','اليوم'],['week','هذا الأسبوع - السبت إلى الجمعة'],['month','هذا الشهر'],['year','هذه السنة'],['custom','فترة أختارها']])+field('from','من تاريخ',f.from,'date','required')+field('to','إلى تاريخ',f.to,'date','required')+select('group','تجميع الجدول',f.group,Object.entries(reportGroupLabels))+'<button class=\"btn\" id=\"showReport\">عرض التقرير</button></div></form><div class=\"note\">الأوقات بتوقيت بغداد، والتصنيف حسب تاريخ إنشاء الطلب. المبيعات تشمل المكتمل فقط؛ المؤكد والمنتظر والمرفوض والملغي لا يدخلون بقيمة المبيعات. صافي مبيعات المنتجات بعد الخصم ودون التوصيل ليس صافي الربح.</div><div id=\"reportResults\"></div><div class=\"card\"><div class=\"flex between\"><div><h3>فواتير الفترة</h3><p class=\"muted\">PDF يتولد عند التحميل على جهازك. الأرشفة ترتب القائمة وتحافظ على الطلب والتقرير.</p></div><label>عرض الفواتير<select id=\"invoiceArchive\"><option value=\"active\">غير المؤرشفة</option><option value=\"archived\">المؤرشفة</option><option value=\"all\">الكل</option></select></label></div><div id=\"invoiceResults\"></div></div>';\n $('#invoiceArchive').value=f.archive;\n $('#reportForm [name=preset]').onchange=ev=>{const value=ev.target.value;if(value!=='custom'){const dates=reportPreset(value);for(const k of ['from','to','group'])$('#reportForm [name='+k+']').value=dates[k]}};\n for(const k of ['from','to'])$('#reportForm [name='+k+']').onchange=()=>{$('#reportForm [name=preset]').value='custom'};\n $('#reportForm').onsubmit=ev=>{ev.preventDefault();const values=Object.fromEntries(new FormData(ev.target));state.reportFilters={...state.reportFilters,...values};loadReports()};\n $('#reportForm').oninput=()=>{$('#exportReport').disabled=true};\n $('#invoiceArchive').onchange=ev=>{state.reportFilters.archive=ev.target.value;loadInvoiceList(1)};\n $('#exportReport').onclick=()=>{try{if(!state.reportData)throw Error('اعرض التقرير أولاً');if(!window.AlqamiInvoice?.downloadReport)throw Error('جاري تحميل أداة PDF؛ حاول بعد لحظات.');window.AlqamiInvoice.downloadReport(state.reportData)}catch(err){toast(err.message)}};\n loadReports();\n}\nfunction metricCard(label,value,color=''){return '<div class=\"card metric '+color+'\"><span class=\"muted\">'+e(label)+'</span><strong>'+e(value)+'</strong></div>'}\nasync function loadReports(){\n const run=++reportRun,button=$('#showReport'),out=$('#reportResults');if(!out)return;\n button.disabled=true;$('#exportReport').disabled=true;state.reportData=null;out.innerHTML='<p class=\"muted\">جاري احتساب التقرير...</p>';\n try{const result=await api('/api/admin/reports?'+reportQuery(state.reportFilters));if(run!==reportRun||state.tab!=='reports')return;state.reportData=result.report;const {summary:s,buckets}=result.report;\n out.innerHTML='<div class=\"report-metrics\">'+metricCard('كل الطلبات',s.total_orders)+metricCard('مستلمة / مكتملة',s.received,'positive')+metricCard('مرفوضة',s.rejected)+metricCard('ملغاة',s.cancelled)+metricCard('منتظرة / مؤكدة',s.pending+s.confirmed)+metricCard('قيمة المكتمل شامل التوصيل',money(s.sales_total),'positive')+metricCard('مبيعات المنتجات بعد الخصم',money(s.net_products))+metricCard('أجور توصيل المكتمل',money(s.delivery))+'</div><div class=\"card\"><h3>تفاصيل الفترة حسب التجميع</h3><div class=\"table-scroll\"><table><thead><tr><th>الفترة</th><th>كل الطلبات</th><th>مستلمة</th><th>مرفوضة</th><th>ملغاة</th><th>قيد المعالجة</th><th>قيمة المكتمل</th></tr></thead><tbody>'+buckets.map(b=>'<tr><td>'+e(b.period)+'</td><td>'+b.total_orders+'</td><td>'+b.received+'</td><td>'+b.rejected+'</td><td>'+b.cancelled+'</td><td>'+(b.pending+b.confirmed)+'</td><td>'+money(b.sales_total)+'</td></tr>').join('')+(buckets.length?'':'<tr><td colspan=\"7\">لا توجد طلبات خلال الفترة المختارة.</td></tr>')+'</tbody><tfoot><tr><th>المجموع</th><th>'+s.total_orders+'</th><th>'+s.received+'</th><th>'+s.rejected+'</th><th>'+s.cancelled+'</th><th>'+(s.pending+s.confirmed)+'</th><th>'+money(s.sales_total)+'</th></tr></tfoot></table></div><p class=\"muted\">مجموع التخفيضات على المكتمل: '+money(s.discounts)+'</p></div>';\n $('#exportReport').disabled=false;await loadInvoiceList(1);\n }catch(err){if(run===reportRun&&state.tab==='reports')out.innerHTML='<p class=\"note\">'+e(err.message)+'</p>'}\n finally{if(run===reportRun&&button.isConnected)button.disabled=false}\n}\nlet invoiceRun=0;\nasync function loadInvoiceList(page=1){\n const box=$('#invoiceResults');if(!box)return;const run=++invoiceRun;box.innerHTML='<p class=\"muted\">جاري تحميل الفواتير...</p>';\n try{const params=reportQuery(state.reportFilters)+'&archive='+state.reportFilters.archive+'&page='+page,result=await api('/api/admin/invoices?'+params);if(run!==invoiceRun||state.tab!=='reports')return;\n let previousDate='';const rows=result.invoices.map(o=>{let head='';if(o.invoice_date!==previousDate){previousDate=o.invoice_date;head='<tr class=\"invoice-date-row\"><td colspan=\"5\">'+e(o.invoice_date)+'</td></tr>'}return head+'<tr><td>'+e(o.id.slice(0,8))+'</td><td>'+e(o.customer_name)+'</td><td><span class=\"status-badge '+e(o.status)+'\">'+e(orderStatuses[o.status]||o.status)+'</span></td><td>'+money(o.total)+'</td><td><div class=\"order-actions\"><button class=\"btn alt\" data-invoice=\"'+e(o.id)+'\">تحميل PDF</button><button class=\"btn alt\" data-archive-invoice=\"'+e(o.id)+'\" data-archived=\"'+(o.invoice_archived?1:0)+'\">'+(o.invoice_archived?'استعادة':'أرشفة')+'</button></div></td></tr>'}).join('');\n const pages=Math.max(1,Math.ceil(result.total/result.page_size));box.innerHTML='<p class=\"muted\">'+result.total+' فاتورة ضمن الفلتر</p><div class=\"table-scroll\"><table><thead><tr><th>الطلب</th><th>الزبون</th><th>الحالة</th><th>الإجمالي</th><th>الإجراءات</th></tr></thead><tbody>'+rows+(rows?'':'<tr><td colspan=\"5\">لا توجد فواتير ضمن هذا الفلتر.</td></tr>')+'</tbody></table></div><div class=\"flex between\" style=\"margin-top:15px\"><button class=\"btn alt\" id=\"invoicePrev\" '+(page<=1?'disabled':'')+'>السابق</button><span>صفحة '+page+' / '+pages+'</span><button class=\"btn alt\" id=\"invoiceNext\" '+(page>=pages?'disabled':'')+'>التالي</button></div>';\n state.invoicePage=page;$('#invoicePrev').onclick=()=>loadInvoiceList(page-1);$('#invoiceNext').onclick=()=>loadInvoiceList(page+1);\n $$('[data-invoice]').forEach(b=>b.onclick=()=>downloadInvoice(b.dataset.invoice,b));$$('[data-archive-invoice]').forEach(b=>b.onclick=()=>archiveInvoice(b.dataset.archiveInvoice,Number(b.dataset.archived)===0,b));\n }catch(err){if(run===invoiceRun&&box.isConnected)box.innerHTML='<p class=\"note\">'+e(err.message)+'</p>'}\n}\nasync function archiveInvoice(id,archived,button){\n button.disabled=true;\n try{await api('/api/admin/orders/'+encodeURIComponent(id)+'/invoice-archive',{method:'PATCH',body:JSON.stringify({archived})});const o=state.orders.find(x=>x.id===id);if(o)o.invoice_archived=archived?1:0;toast(archived?'تمت أرشفة الفاتورة؛ الطلب والمبيعات محفوظة.':'تمت استعادة الفاتورة');if(state.tab==='reports')await loadInvoiceList(1);else render()}\n catch(err){toast(err.message);button.disabled=false}\n}\n\n/* ALQAMI_REPORTS_END */\n$('#closeDialog').onclick=()=>$('#dialog').close();\n$('#editForm').onsubmit=async ev=>{ev.preventDefault();const btn=$('#saveDialog'),d=Object.fromEntries(new FormData(ev.target)),edit=state.edit;btn.disabled=true;try{let path,method='POST';if(edit.kind==='product'){const discount=readProductDiscount();const files=Array.from($('#productFiles')?.files||[]);if(state.editImages.length+files.length>8)throw Error('الحد الأعلى 8 صور للمنتج');const uploaded=await uploadFiles(files);d.images=[...state.editImages,...uploaded];d.active=Number(d.active);d.price=Number(d.price);d.sale_price=discount.salePrice;delete d.discount_kind;delete d.discount_value;path='/api/admin/products'+(edit.id?'/'+encodeURIComponent(edit.id):'');method=edit.id?'PUT':'POST'}else if(edit.kind==='coupon'){path='/api/admin/coupons'+(edit.id?'/'+encodeURIComponent(edit.id):'');method=edit.id?'PUT':'POST';for(const k of ['value','min_total','max_uses','enabled','allow_stacking'])d[k]=Number(d[k]);if(d.scope==='all')d.scope_ids=[];else if(d.scope==='category')d.scope_ids=[$('#scopeCategory').value];else d.scope_ids=Array.from($('#scopeProducts').selectedOptions).map(x=>x.value);d.starts_at=utcCouponDate(d.starts_at);d.ends_at=utcCouponDate(d.ends_at)}else{path='/api/admin/orders/'+encodeURIComponent(edit.id);method='PATCH'}await api(path,{method,body:JSON.stringify(d)});$('#dialog').close();toast('تم الحفظ بنجاح');await load()}catch(err){toast(err.message)}finally{btn.disabled=false}};\n$('#loginForm').onsubmit=async ev=>{ev.preventDefault();try{await api('/api/admin/login',{method:'POST',body:JSON.stringify({password:$('#password').value})});$('#password').value='';await load()}catch(err){toast(err.message)}};\n$$('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render()});$('#logout').onclick=async()=>{await api('/api/admin/logout',{method:'POST',body:'{}'});show(false)};load();\n</script></body></html>\r\n";
import {readReport,readInvoices,orderView} from './reporting.mjs';
import INVOICE_JS from './invoice/invoice.bundle.txt';
const DELIVERY_FEE=6000;
const enc = new TextEncoder();
const j = (obj, status=200, headers={}) => new Response(JSON.stringify(obj),{status,headers:{'Content-Type':'application/json;charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff',...headers}});
const bad=(message,status=400)=>j({ok:false,error:message},status);
const norm=s=>String(s??'').trim();
const validNum=(v,min=0,max=1000000000)=>Number.isSafeInteger(Number(v))&&Number(v)>=min&&Number(v)<=max;
const couponCode=s=>norm(s).replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632)).replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776)).toUpperCase();
const keyOK=s=>/^[A-Z0-9_-]{4,32}$/.test(s);
const now=()=>new Date().toISOString().slice(0,19).replace('T',' ');
const sqlDate=v=>{
 if(v===null||v===undefined||v==='')return null;
 const raw=String(v).trim().replace(' ','T');
 if(!/^\d{4}-\d\d-\d\dT\d\d:\d\d(?::\d\d(?:\.\d{1,3})?)?(?:Z|[+-]\d\d:\d\d)?$/.test(raw))throw Error('صيغة التاريخ غير صحيحة');
 // Legacy/local clients without a zone are interpreted as Baghdad, never server-local time.
 const value=new Date(/(?:Z|[+-]\d\d:\d\d)$/.test(raw)?raw:raw+'+03:00');
 if(Number.isNaN(value.getTime()))throw Error('صيغة التاريخ غير صحيحة');
 return value.toISOString().slice(0,19).replace('T',' ');
};
const baghdadDate=v=>new Intl.DateTimeFormat('ar-IQ',{timeZone:'Asia/Baghdad',dateStyle:'short',timeStyle:'short'}).format(new Date(v.replace(' ','T')+'Z'));
// Same business number already published on the storefront; env can override it.
const DEFAULT_SHOP_WHATSAPP='9647706050050';
function whatsappRecipient(env){
 let number=norm(env.SHOP_WHATSAPP||DEFAULT_SHOP_WHATSAPP).replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632)).replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776)).replace(/[+\s()-]/g,'');
 if(number.startsWith('00'))number=number.slice(2);
 if(/^07\d{9}$/.test(number))number='964'+number.slice(1);
 if(!/^[1-9]\d{7,14}$/.test(number))throw Error('رقم واتساب المتجر غير مهيأ بشكل صحيح. لم يتم تسجيل طلب جديد؛ تواصل مع المتجر.');
 return number;
}
function orderResponse(order,recipient,repeat=false){
 const items=JSON.parse(order.items_json);
 if(!Array.isArray(items)||!items.length)throw Error('تفاصيل الطلب غير متاحة');
 const code=order.coupon_code_snapshot||order.coupon_code;
 const text=['طلب العلقمي #'+order.id.slice(0,8),'الاسم: '+order.customer_name,'الهاتف: '+order.phone,'المحافظة: '+order.province,'العنوان: '+order.address,...items.map(l=>l.name+' × '+l.qty+' — '+l.total+' د.ع'),'مجموع المنتجات قبل الخصومات: '+order.subtotal+' د.ع',Number(order.product_discount)>0?'تخفيض المنتجات: '+order.product_discount+' د.ع':'',Number(order.coupon_discount)>0?'خصم الكوبون: '+order.coupon_discount+' د.ع':'','أجور التوصيل: '+Number(order.delivery_fee||0)+' د.ع','المبلغ النهائي شامل التوصيل: '+order.total+' د.ع',code?'الكوبون: '+code:'','أجور التركيب، إن طلبت، تتفق عليها الإدارة بصورة منفصلة.'].filter(Boolean).join('\n');
 return {ok:true,order_id:order.id,total:order.total,delivery_fee:Number(order.delivery_fee||0),status:order.status||'new',delivery_status:'unconfirmed',repeat,whatsapp_url:'https://wa.me/'+recipient+'?text='+encodeURIComponent(text)};
}
function sameCheckout(order,d){
 const saved=JSON.parse(order.items_json).map(x=>({id:x.id,qty:x.qty})).sort((a,b)=>a.id.localeCompare(b.id));
 const items=Array.isArray(d.items)?d.items.map(x=>({id:norm(x.id),qty:Number(x.qty)})).sort((a,b)=>a.id.localeCompare(b.id)):[];
 return order.customer_name===norm(d.customer_name)&&order.phone===norm(d.phone)&&order.province===norm(d.province)&&order.address===norm(d.address)&&couponCode(order.coupon_code_snapshot||order.coupon_code)===couponCode(d.coupon)&&JSON.stringify(saved)===JSON.stringify(items);
}
const to64=a=>btoa(String.fromCharCode(...a)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
const from64=s=>Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));
async function signKey(secret){return crypto.subtle.importKey('raw',enc.encode(secret),{name:'HMAC',hash:'SHA-256'},false,['sign','verify'])}
async function createToken(secret){const body=to64(enc.encode(JSON.stringify({exp:Date.now()+21600000,nonce:crypto.randomUUID()})));const sig=to64(new Uint8Array(await crypto.subtle.sign('HMAC',await signKey(secret),enc.encode(body))));return body+'.'+sig}
async function auth(request,env){const m=(request.headers.get('Cookie')||'').match(/(?:^|;\s*)alq_admin=([^;]+)/);if(!m||!env.AUTH_KEY)return false;const v=m[1].split('.');if(v.length!==2||m[1].length>1900)return false;try{const ok=await crypto.subtle.verify('HMAC',await signKey(env.AUTH_KEY),from64(v[1]),enc.encode(v[0]));const body=JSON.parse(new TextDecoder().decode(from64(v[0])));return !!ok&&Number.isSafeInteger(body.exp)&&body.exp>Date.now()}catch{return false}}
async function equalHash(a,b){const [u,v]=await Promise.all([crypto.subtle.digest('SHA-256',enc.encode(a)),crypto.subtle.digest('SHA-256',enc.encode(b))]);const x=new Uint8Array(u),y=new Uint8Array(v);let difference=0;for(let i=0;i<32;i++)difference|=x[i]^y[i];return difference===0}
async function body(request,max=30000){const len=Number(request.headers.get('Content-Length')||0);if(len>max)throw Error('حجم الطلب كبير');const s=await request.text();if(s.length>max)throw Error('حجم الطلب كبير');return JSON.parse(s||'{}')}
function cors(req){const origin=req.headers.get('Origin');return origin==='https://awjnob1988-hash.github.io'?{'Access-Control-Allow-Origin':origin,'Access-Control-Allow-Methods':'GET,POST,OPTIONS','Access-Control-Allow-Headers':'Content-Type','Vary':'Origin'}:{}}
