async function lineItems(db,items){if(!Array.isArray(items)||items.length<1||items.length>30)throw Error('السلة غير صالحة');const lines=[],seen=new Set();for(const x of items){const id=norm(x.id),qty=Number(x.qty);if(seen.has(id)||!validNum(qty,1,20))throw Error('الكمية غير صحيحة');seen.add(id);const p=await db.prepare('SELECT id,name,category,price,sale_price FROM products WHERE id=? AND active=1').bind(id).first();if(!p)throw Error('منتج غير متوفر حالياً');const unit=p.sale_price===null?p.price:p.sale_price;lines.push({id,name:p.name,category:p.category,qty,price:p.price,sale_price:p.sale_price,unit,total:unit*qty,discount:(p.price-unit)*qty})}return lines}
